from collections import Counter
def comps(g,bg,conn=8):
    Hh,Ww=len(g),len(g[0]); seen=set(); res=[]
    for r in range(Hh):
        for c in range(Ww):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in range(-1,2):
                        for dx in range(-1,2):
                            if dy==0 and dx==0: continue
                            if conn==4 and abs(dy)+abs(dx)!=2: continue
                            ny,nx=y+dy,x+dx
                            if 0<=ny<Hh and 0<=nx<Ww and g[ny][nx]==col and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                rs=[y for y,x in cells]; cs=[x for y,x in cells]
                t,l=min(rs),min(cs); h=max(rs)-t+1; w=max(cs)-l+1
                mk=frozenset((y-t,x-l) for y,x in cells)
                res.append(dict(col=col,n=len(cells),top=t,left=l,h=h,w=w,cells=sorted(cells),mask=mk))
    return res
